 function showEmailPolicy(){if(managed)return;const isTeacher=register.elements.role.value==='teacher';app.querySelector('#register-email-label').textContent=isTeacher?'Correo institucional':'Correo';app.querySelector('#register-email-help').textContent=isTeacher?'Para ingresar como docente necesitas un correo institucional @upch.pe y puede requerirse autorización administrativa.':''}
