async function home(){window.stopSIDETutorial?.(app.querySelector('.tutorial-shell'));if(supabase){user=await supabase.identity();const currentSession=(await supabase.session())?.session;user.course=String(currentSession?.user?.user_metadata?.curso||'');}const isGuest=supabase?(await supabase.session())?.session?.user?.is_anonymous===true:false;clearInterval(timer);current=null;logout.classList.remove('hidden');const games=await api('/games');catalog=await api('/catalog');if(recoveryPending)return;app.innerHTML=`<section class="toolbar"><div><p class="eyebrow">Bienvenido, ${esc(user.display_name||user.name)}</p><h1>Mis partidas</h1></div></section><div class="layout"><section class="panel"><h2>Partidas disponibles</h2><div class="list">${games.length?games.map(g=>`<button class="secondary" data-game="${esc(g.id)}">${esc(g.name)}</button>`).join(''):'Aún no tienes partidas.'}</div></section><section class="panel">${user.role==='teacher'?`<h2>Crear partida</h2><form id="create"><label>Nombre<input name="name" required value="Mi partida"></label><div class="row"><label>Ciclos<select name="cycleCount"><option>3</option><option>6</option></select></label><label>Segundos por ciclo<input type="number" name="duration" value="120" readonly aria-label="Segundos por ciclo: 120"></label></div><div class="row"><label>Capital mínimo<input name="capitalMin" type="number" min="20000" max="100000" step="10000" value="20000"></label><label>Capital máximo<input name="capitalMax" type="number" min="20000" max="100000" step="10000" value="100000"></label></div><div class="row"><label>Costo básico<input name="basic" type="number" min="1" value="50"></label><label>Costo estándar<input name="standard" type="number" min="1" value="80"></label><label>Costo prémium<input name="premium" type="number" min="1" value="120"></label></div><strong>Eventos activos</strong><div class="events">${catalog.map(x=>`<label><input type="checkbox" name="events" value="${esc(x.id)}"> ${esc(x.label)} <small>${esc(eventDescription(x))}</small></label>`).join('')}</div><p><button>Crear partida</button></p></form>`:`${neon?'<button id="activate-teacher" type="button" class="secondary">Ingresar como docente</button><p class="field-help">Para ingresar como docente necesitas un correo institucional @upch.pe y puede requerirse autorización administrativa.</p>':''}<h2>Unirse a una partida</h2><form id="join"><label>Código<input name="code" required></label><label>Nombre de tu empresa<input name="name" required></label>${isGuest?'<label>Nombre comercial<input name="brand" required></label>':''}<button>Unirme</button></form>`}</section></div>`;if(user.role==='teacher')styleTeacherHome();else styleStudentHome();document.querySelectorAll('[data-game]').forEach(b=>b.onclick=run(()=>openGame(b.dataset.game)));const create=document.querySelector('#create');if(create)create.onsubmit=run(async e=>{e.preventDefault();const f=new FormData(create),g=await api('/games','POST',{name:f.get('name'),cycleCount:+f.get('cycleCount'),duration:+f.get('duration'),capitalMin:+f.get('capitalMin'),capitalMax:+f.get('capitalMax'),costs:{basic:+f.get('basic'),standard:+f.get('standard'),premium:+f.get('premium')},events:f.getAll('events')});await openGame(g.id)});const activate=document.querySelector('#activate-teacher');if(activate)activate.onclick=run(async()=>{await api('/teacher/activate','POST',{});user=await api('/me');await home()});const join=document.querySelector('#join');if(join)join.onsubmit=run(async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(join)),entry={...values,code:values.code.trim().toUpperCase(),name:values.name.trim(),...(isGuest?{brand:values.brand.trim()}:{})};const co=isGuest?await submitGuestJoin(entry):await api('/join','POST',entry);await openGame(co.game_id)})}
// Usa la estructura de acceso y sala de SIDE conservando los formularios Lite.
function styleStudentHome(){
 const layout=app.querySelector(':scope > .layout');if(!layout)return;
 const [games,join]=layout.children;const form=join.querySelector('#join');
 const shell=document.createElement('section');shell.className='student-home dashboard-screen';
 const background=document.createElement('div');background.className='dashboard-bg';background.setAttribute('aria-hidden','true');
 const inner=document.createElement('div');inner.className='dashboard-inner lobby';
 const card=document.createElement('div');card.className='lobby-card';
 const logo=document.createElement('img');logo.src='assets/logo-side.png';logo.className='dash-logo';logo.alt='SIDE';
 const header=document.createElement('div');header.className='lobby-content';
 const eyebrow=document.createElement('p');eyebrow.className='eyebrow';eyebrow.textContent='PARTIDA';
 const title=document.createElement('h1');title.textContent='Entrar a una partida';
 const lead=document.createElement('p');lead.textContent='Introduce el código que te entregó tu profesor.';
 header.append(eyebrow,title,lead);
 if(form){form.classList.add('student-join-form');header.append(form)}
 const activation=join.querySelector('#activate-teacher');if(activation){header.append(activation);const help=join.querySelector('.field-help');if(help)header.append(help)}
 games.classList.add('student-game-list');header.append(games);card.append(logo,header);inner.append(card);shell.append(background,inner);
 app.querySelector(':scope > .toolbar')?.remove();layout.replaceWith(shell);
}
