  grid.append(card('Identificación','Partida',[name,courseLabel,codeLabel]),card('Duración y ciclos','Configuración',[rows[0]]),card('Caja / efectivo','Capital inicial',[rows[1]]),card('Costos por calidad','Productos',[rows[2]]));
  const eventCard=card('Eventos habilitados','Durante la partida',[eventTitle,events]);eventCard.classList.add('events-config-summary');
  form.append(grid,eventCard);if(submit){const footer=document.createElement('div');footer.className='config-start-footer';const note=document.createElement('div');note.innerHTML='<strong>Revisa la configuración antes de iniciar.</strong><p>Iniciar partida abre la sala de espera.</p>';const button=submit.querySelector('button');footer.append(note);if(button){button.textContent='Iniciar partida';button.classList.add('primary');footer.append(button)}submit.remove();form.append(footer)}
