 app.querySelector('#faculty-config').append(form);app.querySelector('#faculty-game-list').append(list);renderLaboratory(app.querySelector('#faculty-lab'));app.querySelector('#teacher-home').onclick=run(home);app.querySelector('#teacher-logout').onclick=()=>logout.click();
 const links=[...app.querySelectorAll('.sidebar nav .nav-btn')];links[0]?.classList.add('active');links.forEach(link=>link.addEventListener('click',()=>{links.forEach(item=>item.classList.toggle('active',item===link))}));
