 const companySelect=app.querySelector('#resultCompanySelect');companySelect.value=[...companySelect.options].some(option=>option.value===teacherResultCompany)?teacherResultCompany:'';const filterResults=()=>{teacherResultCompany=companySelect.value;let shown=0;app.querySelectorAll('[data-result-company]').forEach(report=>{report.hidden=!!teacherResultCompany&&report.dataset.resultCompany!==teacherResultCompany;if(!report.hidden)shown++});app.querySelector('#result-company-empty').hidden=!teacherResultCompany||shown>0};companySelect.addEventListener('change',filterResults);filterResults();
