 const selectTab=id=>{if(id==='podio'&&!neon&&!podiumMounted){podiumMounted=true;renderTeacherPodium(app.querySelector('#faculty-podium-tools'),{gameId:g.id,request:api})}if(id==='historial'&&!historyMounted){historyMounted=true;renderTeacherHistory(app.querySelector('#faculty-history'),{listGames:()=>api('/games'),loadGame:gameId=>api('/games/'+gameId)})}teacherActiveTab=id;for(const [tab,label] of tabs){const active=id===tab;app.querySelector('#tab-'+tab).hidden=!active;const btn=app.querySelector(`[data-tab="${tab}"]`);btn.classList.toggle('active',active);btn.setAttribute('aria-current',active?'page':'false');if(active)app.querySelector('#faculty-page-title').textContent=label}};
 app.querySelectorAll('nav [data-tab]').forEach(button=>button.addEventListener('click',()=>selectTab(button.dataset.tab)));selectTab(teacherActiveTab);
 app.querySelector('#back').onclick=run(home);app.querySelector('#teacher-home').onclick=run(home);app.querySelector('#teacher-logout').onclick=()=>logout.click();app.querySelector('#copy-game-code').onclick=run(async()=>{if(!navigator.clipboard?.writeText)throw Error('No se pudo copiar. Selecciona el código de la pantalla.');await navigator.clipboard.writeText(g.code);app.querySelector('#copy-game-code').textContent='Código copiado';});app.querySelector('#start').onclick=run(async()=>{await api('/games/'+current+'/start','POST',{});await refresh()});const toggle=app.querySelector('#cycle-toggle'),close=app.querySelector('#cycle-close');if(toggle)toggle.onclick=run(async()=>{if(supabase)await api('/games/'+current+'/'+(cy.paused_at?'resume':'pause'),'POST',{});else await api('/games/'+current+'/cycle-control','POST',{action:cy.paused_at?'resume':'pause'});await refresh()});const finish=app.querySelector('#game-finish');if(finish)finish.onclick=run(async()=>{if(!window.confirm('¿Finalizar esta partida? No se podrán iniciar más ciclos.'))return;await api('/games/'+current+'/finish','POST',{});await refresh()});if(close)close.onclick=run(async()=>{await api('/games/'+current+'/cycle-control','POST',{action:'close'});await refresh()});
