// A stalled network request must never permanently stop synchronization. Late
// responses are ignored by refreshVersion, including after changing games.
async function timedRefresh(){let timeout;const request={expired:false};try{await Promise.race([refresh(true,request),new Promise((_,reject)=>{timeout=setTimeout(()=>{request.expired=true;reject(Error('Tiempo de actualización agotado'))},8000)})])}finally{clearTimeout(timeout)}}

async function mountWaitingTutorial(lobby){
 try { const response=await fetch('tutorial.html'); if(!response.ok)throw Error('Tutorial no disponible'); const html=await response.text(); if(!lobby.isConnected)return; const mount=lobby.querySelector('#waitingTutorialMount');mount.innerHTML=html;const label=mount.querySelector('.tutorial-required');if(label)label.textContent='APRENDE MIENTRAS ESPERAS';window.initSIDETutorial?.(null,{root:mount.querySelector('.tutorial-shell'),loop:true}); } catch { const mount=lobby.querySelector('#waitingTutorialMount');if(mount)mount.textContent='No se pudo cargar el tutorial.'; }
}
let studentLobbyOpen=true;
async function openGame(id){studentLobbyOpen=true;clearInterval(timer);refreshVersion++;if(current!==id){teacherActiveTab="rondas";teacherResultCompany="";}current=id;await refresh();let disconnected=false,ticks=0,polling=false;timer=setInterval(async()=>{updateClock();if(++ticks%3||polling)return;polling=true;try{await timedRefresh();if(disconnected){error.textContent='Conexión recuperada. Revisa y guarda tus cambios.';disconnected=false}}catch(e){if(e.status===401){error.textContent='Tu sesión terminó. Vuelve a iniciar sesión.'}else if(e.status){error.textContent='No se pudo actualizar la partida. Inténtalo de nuevo.'}else{disconnected=true;error.textContent='Sin conexión. Tus cambios en pantalla aún no están guardados; vuelve a intentarlo al recuperar la conexión.'}}finally{polling=false}},1000)}
async function refresh(background=false,request=null){const requestStarted=performance.now(),version=++refreshVersion,gameId=current,previousCycle=app.dataset.cycleId;const d=await api('/games/'+gameId);if(request?.expired||version<appliedRefreshVersion||gameId!==current)return;appliedRefreshVersion=version;const existing=document.querySelector('#decision');const unsaved=background&&existing?.dataset.dirty==='true'?Object.fromEntries(new FormData(existing)):null;const g=d.game,cy=d.cycles.at(-1),open=cy&&cy.status==='open',own=d.ownDecision;const signature=JSON.stringify([g,cy&&{...cy,server_now:undefined},own,d.results,d.companies,d.decisions,d.ranking]);if(background&&app.dataset.signature===signature){clock(cy,requestStarted);if(!neon&&!d.isTeacher&&cy?.status==='closed'&&cy.number===g.cycle_count)void showStudentPodium(g.id);return}app.dataset.signature=signature;app.dataset.cycleId=cy?.id||'';if(d.isTeacher){renderTeacherGame(d,g,cy,open);clock(cy,requestStarted);return}let content=`<div class="toolbar"><div><button id="back" class="secondary">Mis partidas</button><h1>${esc(g.name)}</h1></div><div><strong>Código: ${esc(g.code)}</strong><p id="clock"></p></div></div><section class="summary"><div><span>Ciclo</span><strong>${cy?cy.number:0} de ${g.cycle_count}</strong></div><div><span>Estado</span><strong id="cycle-status">${open?'En curso':cy?'Cerrado':'Por iniciar'}</strong></div><div><span>Evento</span><strong>${esc(catalog.find(x=>x.id===cy?.event_id)?.label||'Sin evento')}</strong></div><div><span>Empresas</span><strong>${d.companies.length}</strong></div></section><p class="event-note">${esc(eventDescription(catalog.find(x=>x.id===cy?.event_id)))}</p><p id="processing-notice" class="processing hidden" role="status">El tiempo terminó. Estamos procesando los resultados oficiales.</p><div class="layout"><section class="panel">`;
if(d.isTeacher){content+=`<h2>Supervisión</h2><p>${cy?.number>=g.cycle_count&&!open?'Partida finalizada.':'Inicia el siguiente ciclo cuando todos estén listos.'}</p><button id="start" ${open||cy?.number>=g.cycle_count?'disabled':''}>Iniciar ciclo</button><table><tr><th>Empresa</th><th>Tienda</th><th>Decisión</th></tr>${d.companies.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.store)}</td><td>${d.decisions.find(x=>x.company_id===c.id)?.confirmed?'Confirmada':'Pendiente'}</td></tr>`).join('')}</table>`}else {const c=d.companies.find(x=>x.id===d.company.id);content+=`<h2>${esc(c.name)} · ${esc(c.store)}</h2><p>Capital inicial: <strong>${money(c.initial_capital)}</strong> · Caja disponible: <strong>${money(c.cash)}</strong> · Inventario: ${c.inventory.reduce((n,b)=>n+b.quantity,0)} bolsos</p>`;if(open&&!cy.paused_at&&!cy.close_requested_at&&!own?.confirmed){content+=`<form id="decision"><label>Calidad<select name="quality"><option value="basic">Básico · ${money(g.costs.basic)}</option><option value="standard">Estándar · ${money(g.costs.standard)}</option><option value="premium">Prémium · ${money(g.costs.premium)}</option></select><span id="quality-help" class="field-help"></span></label><div class="row"><label>Cantidad <span class="field-help">¿Cuántos bolsos quieres producir este ciclo?</span><input name="quantity" type="number" min="0" max="100000" required value="${own?.quantity??0}"></label><label>Precio <span class="field-help">¿A cuánto venderás cada bolso?</span><input name="price" type="number" min="1" max="100000" required value="${own?.price??100}"></label></div><section class="campaign-section" aria-labelledby="marketing-title"><h3 id="marketing-title">¿Cuánto quieres invertir en publicidad?</h3><p class="campaign-subtitle">Haz que más personas conozcan tu tienda.</p><label for="marketing-amount">Inversión en soles</label><div class="campaign-controls"><div class="amount-input"><span aria-hidden="true">S/</span><input id="marketing-amount" name="marketingAmount" type="number" min="0" max="10000" step="1" value="${own?.marketing_amount??0}" required aria-describedby="marketing-rule"></div><input id="slider" type="range" min="0" max="10000" step="1" value="${own?.marketing_amount??0}" aria-label="Ajustar inversión en publicidad"></div><p id="marketing-rule" class="field-help">S/ 0 o cualquier monto entero entre S/ 200 y S/ 10.000.</p><div class="campaign-card" aria-live="polite"><div class="campaign-icon" id="campaign-icon" aria-hidden="true">○</div><div><strong id="campaign-name"></strong><span id="campaign-range"></span><p id="campaign-description"></p><small id="campaign-message"></small></div></div><p class="campaign-spend">Gasto del ciclo: <strong id="campaign-spend"></strong></p><p class="field-help">Campaña simulada: no se publican anuncios reales.</p></section><p id="estimate"></p><div class="inline"><button type="submit" name="action" value="draft" class="secondary">Guardar borrador</button><button type="submit" name="action" value="confirm">Confirmar decisión</button></div></form>`}else content+=`<p>${own?.confirmed?'Decisión confirmada.':cy?.paused_at?'Ciclo pausado por el docente.':cy?.close_requested_at?'Cierre solicitado. Estamos procesando resultados.':'Espera a que el docente inicie el ciclo.'}</p><p class="fine">Sin decisión confirmada no se compra, gasta ni vende.</p>`}content+=`</section><aside><section class="panel"><h2>Clasificación</h2><table><tr><th>Empresa</th><th>Rentabilidad</th>${d.isTeacher?'<th>Caja</th>':''}</tr>${d.ranking.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.returnPercent.toFixed(1)} %</td>${d.isTeacher?`<td>${money(r.cash)}</td>`:''}</tr>`).join('')}</table></section><section class="panel"><h2>Resultados</h2>${d.results.length?d.results.filter(r=>d.isTeacher||r.company_id===d.company.id).map(r=>{const c=d.companies.find(x=>x.id===r.company_id),v=r.result;return `<p><strong>Ciclo ${r.number} · ${esc(c?.name)}</strong><br>Vendiste ${v.sold} bolsos por ${money(v.revenue)}.<br>${v.profit<0?'Perdiste':'Ganaste'} ${money(Math.abs(v.profit))}.<br>Quedaron ${v.inventory.reduce((n,b)=>n+b.quantity,0)} bolsos · Caja disponible: ${money(v.cashEnd)}.</p><details><summary>Ver detalle económico</summary><p>Compra: ${money(v.purchase)} · Costo de ventas: ${money(v.costOfSales)} · Marketing: ${money(v.marketing)} · Demanda potencial: ${v.demand}</p></details>`}).join(''):'Aún no hay resultados.'}</section></aside></div>`;window.stopSIDETutorial?.(app.querySelector('.tutorial-shell'));app.innerHTML=content;styleStudentGame(d,g,cy);if(!neon&&cy?.status==='closed'&&cy.number===g.cycle_count)void showStudentPodium(g.id);document.querySelector('#back').onclick=run(home);const start=document.querySelector('#start');if(start)start.onclick=run(async()=>{await api('/games/'+current+'/start','POST',{});await refresh()});const f=document.querySelector('#decision');if(f){if(own)f.quality.value=own.quality;if(unsaved&&previousCycle===cy?.id){f.dataset.dirty='true';for(const field of ['quality','quantity','price','marketingAmount'])f.elements[field].value=unsaved[field];f.querySelector('#slider').value=unsaved.marketingAmount}const update=()=>{const ev=catalog.find(x=>x.id===cy.event_id),cost=Math.round(g.costs[f.quality.value]*(ev?.purchase??1)),purchase=cost*+f.quantity.value,input=f.elements.marketingAmount,m=input.value===''?NaN:Number(input.value),campaign=campaignFor(m);document.querySelector('#quality-help').textContent=({basic:'Bolsos económicos para clientes que buscan ahorrar.',standard:'Bolsos que combinan calidad y precio.',premium:'Bolsos de mayor calidad para clientes exigentes.'})[f.quality.value];input.setCustomValidity(!campaign?'Ingresa S/ 0 o un monto entero entre S/ 200 y S/ 10.000.':purchase+m>d.company.cash?'La compra y el marketing superan tu caja disponible.':'');document.querySelector('#campaign-name').textContent=campaign?.name??'Monto no válido';document.querySelector('#campaign-range').textContent=campaign?.range??'';document.querySelector('#campaign-description').textContent=campaign?.description??'Elige S/ 0 o un monto entre S/ 200 y S/ 10.000.';document.querySelector('#campaign-message').textContent=campaign?.message??'';document.querySelector('#campaign-icon').textContent=campaign?.icon??'!';document.querySelector('#campaign-spend').textContent=campaign?money(m):'—';document.querySelector('#estimate').textContent=campaign?`Compra: ${money(purchase)} · Marketing: ${money(m)} · Disponible tras invertir: ${money(d.company.cash-purchase-m)}`:'Revisa el monto de marketing.'};f.oninput=()=>{f.dataset.dirty='true';update()};f.querySelector('#slider').oninput=e=>{f.marketingAmount.value=e.target.value;update()};f.marketingAmount.oninput=()=>{f.querySelector('#slider').value=f.marketingAmount.value;update()};update();f.onsubmit=run(async e=>{e.preventDefault();if(clockOpen&&deadlineMonotonic!==null&&performance.now()>=deadlineMonotonic){updateClock();throw Error('El tiempo del ciclo terminó. Estamos procesando los resultados.')}const v={quality:f.quality.value,quantity:+f.quantity.value,price:+f.price.value,marketingAmount:+f.marketingAmount.value,confirmed:e.submitter.value==='confirm'};await api('/games/'+current+'/decision','PUT',v);await refresh()})}clock(cy,requestStarted)}
// Estructura de decisiones de SIDE, con las acciones y datos de Lite.
async function showStudentPodium(gameId){try{const data=await api('/games/'+gameId+'/podium');if(current!==gameId)return;const section=app.querySelector('#lite-results');if(!section)return;let panel=section.querySelector('#student-podium');if(!data.published){panel?.remove();return}if(!panel){panel=document.createElement('div');panel.id='student-podium';section.prepend(panel)}panel.replaceChildren();const title=document.createElement('h3');title.textContent='Podio final del profesor';panel.append(title);const list=document.createElement('ol');for(const item of data.published.ranking){const li=document.createElement('li');li.textContent=`${item.name} · ${item.grade} puntos`;list.append(li)}panel.append(list);if(data.published.reason){const reason=document.createElement('p');reason.textContent=data.published.reason;panel.append(reason)}}catch{/* A failed optional panel must not disrupt the game. */}}
function styleStudentGame(d,g,cy){
 const toolbar=app.querySelector(':scope > .toolbar'),summary=app.querySelector(':scope > .summary');
 const note=app.querySelector(':scope > .event-note'),processing=app.querySelector('#processing-notice'),layout=app.querySelector(':scope > .layout');
 if(!toolbar||!layout)return;
 const shell=document.createElement('div');shell.className='student-side';
 if(!cy){
  const lobby=document.createElement('section');lobby.id='studentLobby';lobby.className='dashboard-screen';
  lobby.innerHTML=`<div id="studentWaiting" class="student-waiting" role="region" aria-label="Sala de espera"><div class="game-loading-bg" aria-hidden="true"></div><div class="game-loading-content student-waiting-content"><header class="waiting-header"><div class="waiting-heading"><p class="eyebrow">Sala de espera</p><h1>Aprende cómo jugar</h1><p id="waitingGameName">${esc(g.name)} · ${esc(d.company.name)} · ${esc(g.code)}</p></div><div class="waiting-status"><div class="waiting-clock" role="timer" aria-label="Tiempo restante en la sala de espera"><span>TIEMPO DE SALA DE ESPERA</span><strong id="waitingCountdown">--:--</strong><small id="waitingCountdownNote">Esperando inicio del docente</small></div><p id="waitingCompanies" class="waiting-companies" role="status">${d.companies.length} empresas conectadas</p></div></header><div id="waitingTutorialMount" class="waiting-tutorial-mount" aria-label="Cómo jugar"></div><footer class="waiting-footer"><p id="studentIntegrationNotice" class="hint" role="status">La partida comenzará cuando el docente inicie el ciclo.</p><button id="waitingBackToProfiles" class="ghost-btn" type="button">Volver al inicio</button></footer></div></div>`;
  app.append(lobby);mountWaitingTutorial(lobby);lobby.hidden=!studentLobbyOpen;
  try{const saved=guestSecrets.get(g.id)||JSON.parse(localStorage.getItem('side-lite-guest-'+g.id)||'null');if(saved?.secret){const footer=lobby.querySelector('.waiting-footer'),details=document.createElement('details');details.className='guest-recovery-details';const summary=document.createElement('summary');summary.textContent='Clave privada de recuperación';const explanation=document.createElement('p');explanation.textContent='Guarda esta clave en un lugar seguro. Permite recuperar tu empresa desde otro navegador; no la compartas.';const code=document.createElement('code');code.textContent=saved.secret;details.append(summary,explanation,code);footer.prepend(details)}}catch{/* The active session remains usable if local storage is unavailable. */}shell.hidden=studentLobbyOpen;lobby.querySelector('#waitingBackToProfiles').onclick=()=>app.querySelector('#back').click();
 }
 toolbar.classList.add('decision-topbar');
 const oldTitle=toolbar.querySelector('h1');if(oldTitle)oldTitle.textContent='DECISIONES';
 const identity=toolbar.firstElementChild;if(identity){identity.classList.add('decision-topbar-identity');const sub=document.createElement('small');sub.textContent=`CICLO ${cy?.number||0} · ${d.company?.name||g.name}`;identity.append(sub)}
 const cash=document.createElement('div');cash.className='cash-hud';const label=document.createElement('span');label.textContent='CAJA / EFECTIVO';const amount=document.createElement('strong');amount.textContent=money(d.company?.cash||0);cash.append(label,amount);toolbar.insertBefore(cash,toolbar.lastElementChild);

 const windowEl=document.createElement('section');windowEl.className='decision-window';
 const nav=document.createElement('nav');nav.className='decision-tabs';nav.setAttribute('aria-label','Secciones de la partida');
 const main=layout.querySelector(':scope > section'),panels=layout.querySelectorAll('aside section');
 if(main)main.id='lite-decisions';if(panels[0])panels[0].id='lite-ranking';if(panels[1])panels[1].id='lite-results';
 for(const [id,label] of [['lite-decisions','Decisiones'],['lite-ranking','Clasificación'],['lite-results','Resultados']]){const a=document.createElement('a');a.className='decision-tab';a.href='#'+id;const icon=document.createElement('img');icon.src='assets/icons/categories/'+(id==='lite-decisions'?'canales_ventas':'finanzas')+'.svg';icon.alt='';a.append(icon,document.createTextNode(label));nav.append(a)}
 const detail=document.createElement('div');detail.className='decision-detail';
 if(summary)detail.append(summary);if(note)detail.append(note);if(processing)detail.append(processing);detail.append(layout);windowEl.append(nav,detail);shell.append(toolbar,windowEl);app.append(shell);
}
function clock(cy,requestStarted){clockOpen=!!cy&&cy.status==='open';clockPaused=clockOpen&&!!cy.paused_at;pausedSeconds=clockPaused?Math.max(0,Math.ceil((Date.parse(cy.ends_at)-Date.parse(cy.paused_at))/1000)):0;deadlineMonotonic=clockOpen&&!clockPaused?requestStarted+Math.max(0,Date.parse(cy.ends_at)-Date.parse(cy.server_now)):null;updateClock()}
function updateClock(){const el=document.querySelector('#clock');if(!el)return;const active=clockOpen&&(clockPaused||deadlineMonotonic!==null);if(!active){el.textContent='';return}const seconds=clockPaused?pausedSeconds:Math.max(0,Math.ceil((deadlineMonotonic-performance.now())/1000));const processing=!clockPaused&&seconds===0;el.textContent=processing?'Tiempo finalizado':`${clockPaused?'Pausado':'Tiempo oficial'}: ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;const status=document.querySelector('#cycle-status');if(status)status.textContent=clockPaused?'Pausado':processing?'Procesando resultados':'En curso';document.querySelector('#processing-notice')?.classList.toggle('hidden',!processing);document.querySelector('#decision')?.classList.toggle('hidden',processing||clockPaused)}
if(staticPreview)signin();else try{user=supabase?await supabase.identity():await api('/me');await home()}catch{signin()}
